<?php
require_once __DIR__.'/includes/auth.php';require_permission('dashboard');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE privacy_requests SET status=?,resolution=? WHERE id=?')->execute([$_POST['status'],trim($_POST['resolution']), (int)$_POST['id']]);audit_action('privacy_request_updated','privacy_requests',(int)$_POST['id'],$_POST['status']);flash('success','Privacy request updated.');redirect('privacy_admin.php');}$requests=$pdo->query('SELECT p.*,u.full_name,u.email FROM privacy_requests p LEFT JOIN users u ON u.id=p.user_id ORDER BY p.created_at DESC')->fetchAll();$pageTitle='Privacy requests';$activePage='privacy_admin';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Administration / Data privacy</div><h1>Privacy requests</h1><p>Review resident and staff requests for access, correction, questions, and complaints.</p></div></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Requester</th><th>Type / details</th><th>Submitted</th><th>Status</th><th>Resolution</th><th>Save</th></tr></thead><tbody><?php foreach($requests as $request): ?><tr><td><strong><?= h($request['full_name']??'Unknown') ?></strong><small class="cell-subtext"><?= h($request['email']??'') ?></small></td><td><strong><?= h($request['request_type']) ?></strong><small class="cell-subtext"><?= h($request['details']) ?></small></td><td class="muted"><?= h(date('M d, Y',strtotime($request['created_at']))) ?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= h($request['id']) ?>"><select name="status"><?php foreach(['Received','Under review','Resolved','Denied'] as $status): ?><option <?= $request['status']===$status?'selected':'' ?>><?= h($status) ?></option><?php endforeach; ?></select></td><td><input name="resolution" value="<?= h($request['resolution']??'') ?>" placeholder="Officer note"></td><td><button class="text-button">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
